swift -e '
import Foundation
import ApplicationServices

func axString(_ element: AXUIElement, _ attr: CFString) -> String? {
    var value: CFTypeRef?
    guard AXUIElementCopyAttributeValue(element, attr, &value) == .success else { return nil }
    return value as? String
}

func children(of element: AXUIElement) -> [AXUIElement] {
    var value: CFTypeRef?
    guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &value) == .success else { return [] }
    return (value as? [AXUIElement]) ?? []
}

func findButton(_ element: AXUIElement, title: String) -> AXUIElement? {
    let role = axString(element, kAXRoleAttribute as CFString) ?? ""
    let label = axString(element, kAXTitleAttribute as CFString) ?? axString(element, kAXDescriptionAttribute as CFString) ?? ""
    if role == (kAXButtonRole as String) && label == title { return element }
    for child in children(of: element) {
        if let found = findButton(child, title: title) { return found }
    }
    return nil
}

let pid: pid_t = 35695
let app = AXUIElementCreateApplication(pid)
var windowsValue: CFTypeRef?
guard AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &windowsValue) == .success,
      let windows = windowsValue as? [AXUIElement],
      let window = windows.first else {
    fputs("no window\n", stderr)
    exit(1)
}

if let openButton = findButton(window, title: "Open") {
    let result = AXUIElementPerformAction(openButton, kAXPressAction as CFString)
    print("pressed", result.rawValue)
} else {
    fputs("open button not found\n", stderr)
    exit(2)
}
'
